//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		// Docente: solo ve las cátedras que él dicta
if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "profesor_id = " . intval($_SESSION["profesor_id"]));
}
// Alumno: solo ve las cátedras donde está inscripto
elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "id IN (SELECT curso_id FROM inscripciones WHERE estudiante_id = " . intval($_SESSION["estudiante_id"]) . ")");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$cupo       = intval($values["cupo"]);
$aula       = trim($values["aula"]);
$horario    = trim($values["horario"]);
$periodo_id = intval($values["periodo_id"]);

if ($cupo <= 0) {
    $message = "El cupo máximo del curso debe ser mayor a 0.";
    return false;
}

// Conflicto de aula y horario en el mismo periodo
if (!empty($aula) && !empty($horario)) {
    $sqlConf = "SELECT c.id, m.nombre AS materia 
                FROM cursos c 
                INNER JOIN materias m ON m.id = c.materia_id 
                WHERE c.periodo_id = " . $periodo_id . " 
                  AND c.aula = " . db_prepare_string($aula) . " 
                  AND c.horario = " . db_prepare_string($horario) . " 
                  AND c.estado = 'Activo' LIMIT 1";
    $rsConf = DB::Query($sqlConf);
    if ($conf = $rsConf->fetchAssoc()) {
        $message = "Conflicto de Aula: El Aula <strong>" . htmlspecialchars($aula) . "</strong> ya está ocupada en el horario <strong>" . htmlspecialchars($horario) . "</strong> por la cátedra <em>" . $conf["materia"] . "</em>.";
        return false;
    }
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, $where, &$oldvalues, &$keys, &$message, $inline, &$pageObject)
{

		$id_actual  = isset($keys["id"]) ? intval($keys["id"]) : 0;
$cupo       = intval($values["cupo"]);
$aula       = trim($values["aula"]);
$horario    = trim($values["horario"]);
$periodo_id = intval($values["periodo_id"]);

if ($cupo <= 0) {
    $message = "El cupo máximo debe ser mayor a 0.";
    return false;
}

if (!empty($aula) && !empty($horario)) {
    $sqlConf = "SELECT c.id, m.nombre AS materia 
                FROM cursos c 
                INNER JOIN materias m ON m.id = c.materia_id 
                WHERE c.periodo_id = " . $periodo_id . " 
                  AND c.aula = " . db_prepare_string($aula) . " 
                  AND c.horario = " . db_prepare_string($horario) . " 
                  AND c.estado = 'Activo' 
                  AND c.id != " . $id_actual . " LIMIT 1";
    $rsConf = DB::Query($sqlConf);
    if ($conf = $rsConf->fetchAssoc()) {
        $message = "Conflicto de Aula: El Aula <strong>" . htmlspecialchars($aula) . "</strong> ya está ocupada en ese horario por <em>" . $conf["materia"] . "</em>.";
        return false;
    }
}

return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$curso_id = intval($deleted_values["id"]);
$rsIns = DB::Query("SELECT COUNT(*) AS total FROM inscripciones WHERE curso_id = " . $curso_id);
$rIns = $rsIns->fetchAssoc();

if (intval($rIns["total"]) > 0) {
    $message = "No puede eliminar esta cátedra porque ya cuenta con " . $rIns["total"] . " estudiante(s) inscripto(s). Finalice el curso en su lugar.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



